397	/* Returns an array of floats for one new row, range [0, 1.0] */
398	static double *
399	generate_signal (ModeInfo *mi)
400	{
401	  unk_configuration *bp = &bps[MI_SCREEN(mi)];
402	  double *points = (double *) calloc (sizeof(*points), bp->resolution);
403	  double *p;
404	  int i, j;
405	  int nspikes = (6 + frand(15)) * bp->noise;
406	  double step = 1.0 / bp->resolution;
407	  double r, max;
408	
409	  for (j = 0; j < nspikes; j++)
410	    {
411	      double off = (bp->mask
412	                    ? frand (1.0) - 0.5    /* all the way to the edge */
413	                    : frand (0.8) - 0.4);  /* leave a margin */
414	      double amp = (0.1 + frand (0.9)) * nspikes;
415	      double freq = (7 + frand (11)) * bp->noise;
416	      for (i = 0, r = -0.5, p = points;
417	           i < bp->resolution;
418	           i++, r += step, p++)
419	        *p += amp/2 + amp/2 * cos1 ((r + off) * M_PI * 2 * freq);
420	    }
421	
422	  /* Avoid clipping */
423	  max = nspikes;
424	  if (max <= 0) max = 1;
425	  for (i = 0, p = points; i < bp->resolution; i++, p++)
426	    if (max < *p) max = *p;
427	
428	  /* Multiply by baseline clipping curve, add static. */
429	  for (i = 0, r = -0.5, p = points; i < bp->resolution; i++, r += step, p++)
430	    *p = ((*p / max)
431	          * (0.5 +
432	             0.5
433	             * (bp->mask ? 1 : cos1 (r * r * M_PI * 14))
434	             * (1 - frand(0.2))));
435	
436	  return points;
437	}
