void test_create_image_fills_in_geometry_and_computes_the_row_size(void) {
  XImage *im = XCreateImage(dpy, NULL, 32, ZPixmap, 0, NULL, 7, 3, 32, 0);
  TEST_ASSERT_NOT_NULL(im);
  TEST_ASSERT_EQUAL_INT(7, im->width);
